
const { useEffect, useState } = CMS.React;

const HomepagePreview = ({ entry, getAsset, document: previewDocument }) => {
  const [isReady, setIsReady] = useState(false);

  // Load the actual HTML generated by Astro.
  useEffect(() => {
    let cancelled = false;
    // Prevent the preview iframe from requesting /favicon.ico.
    const favicon = previewDocument.createElement('link');
    favicon.rel = 'icon';
    favicon.href = 'data:,';
    previewDocument.head.appendChild(favicon);

    const previewUrl = new URL(
      '../preview/homepage/',
      window.location.href,
    );

    async function loadPreview() {
      try {
        const response = await fetch(previewUrl);

        if (!response.ok) {
          throw new Error(`Preview request failed: ${response.status}`);
        }

        const htmlText = await response.text();
        const parsedDocument = new DOMParser().parseFromString(
          htmlText,
          'text/html',
        );

        if (cancelled) return;

        const root = previewDocument.getElementById(
          'nycuno-hero-preview-root',
        );

        if (!root) {
          throw new Error('Preview container was not found.');
        }

        // Preserve the Astro page's body classes.
        previewDocument.body.className = parsedDocument.body.className;

        // Copy the stylesheets and font connections into Sveltia's preview.
        parsedDocument.head
          .querySelectorAll(
            'link[rel="stylesheet"], link[rel="preconnect"], style',
          )
          .forEach((node) => {
            const clone = previewDocument.importNode(node, true);

            if (clone.tagName === 'LINK') {
              const href = clone.getAttribute('href');

              if (href) {
                clone.href = new URL(href, previewUrl).href;
              }
            }

            previewDocument.head.appendChild(clone);
          });

        // Insert the actual Astro-rendered Hero markup.
        root.innerHTML = parsedDocument.body.innerHTML;

        setIsReady(true);
      } catch (error) {
        console.error('NYCUNO preview error:', error);

        const root = previewDocument.getElementById(
          'nycuno-hero-preview-root',
        );

        if (root) {
          root.textContent = 'Unable to load the homepage preview.';
        }
      }
    }

    loadPreview();

    return () => {
      cancelled = true;
    };
  }, [previewDocument]);

  // Apply the latest unsaved CMS values to the Astro-rendered markup.
  useEffect(() => {
    if (!isReady) return;

    const hero = entry.getIn(['data', 'hero'])?.toJS();
    const benefits = entry.getIn(['data', 'benefits'])?.toJS();
    const howItWorks = entry.getIn(['data', 'how_it_works'])?.toJS();
    const services = entry.getIn(['data', 'services'])?.toJS();
    const driveWithUs = entry.getIn(['data', 'drive_with_us'])?.toJS();
    const rideOptions = entry.getIn(['data', 'ride_options'])?.toJS();
    const promotionalBanners = entry.getIn(['data', 'promotional_banners'])?.toJS();
    const easyRegistration = entry.getIn(['data', 'easy_registration'])?.toJS();
    const testimonials = entry.getIn(['data', 'testimonials'])?.toJS();
    const safetySupport = entry.getIn(['data', 'safety_support'])?.toJS();

    if (
      !hero &&
      !benefits &&
      !howItWorks &&
      !services &&
      !driveWithUs &&
      !rideOptions &&
      !promotionalBanners &&
      !easyRegistration &&
      !testimonials &&
      !safetySupport
    ) return;

    const setText = (keyPath, value) => {
      previewDocument
        .querySelectorAll(`[data-key-path="${keyPath}"]`)
        .forEach((element) => {
          element.textContent = value ?? '';
        });
    };

    const previewUrl = new URL('../preview/homepage/', window.location.href);
    const siteBase = new URL('../../', previewUrl);

    const resolveImage = (path) => {
      if (!path) return '';

      const cmsAsset = getAsset(path);
      const imagePath = cmsAsset?.url || path;

      if (/^(https?:|blob:|data:)/i.test(imagePath)) {
        return imagePath;
      }

      return new URL(
        imagePath.replace(/^\/+/, ''),
        siteBase,
      ).href;
    };

    // Hero Section
    if (hero) {
      setText('hero.brand_text', hero.brand_text);
      setText('hero.brand_suffix', hero.brand_suffix);
      setText('hero.heading_prefix', hero.heading_prefix);
      setText('hero.heading_highlight', hero.heading_highlight);
      setText('hero.description', hero.description);

      const backgroundUrl = resolveImage(hero.background_image);

      previewDocument
        .querySelectorAll('[data-key-path="hero.background_image"]')
        .forEach((image) => {
          if (backgroundUrl) {
            image.src = backgroundUrl;
          } else {
            image.removeAttribute('src');
          }
        });

      const promotionalUrl = resolveImage(hero.promotional_image);

      previewDocument
        .querySelectorAll('[data-key-path="hero.promotional_image"]')
        .forEach((image) => {
          if (promotionalUrl) {
            image.src = promotionalUrl;
          } else {
            image.removeAttribute('src');
          }

          image.alt = hero.promotional_image_alt ?? '';
        });
    }

    // Why Choose NYC Uno Section
    if (benefits) {
      setText('benefits.heading', benefits.heading);

      (benefits.items ?? []).forEach((benefit, index) => {
        const itemPath = `benefits.items.${index}`;

        setText(`${itemPath}.title`, benefit.title);
        setText(`${itemPath}.description`, benefit.description);

        const iconUrl = resolveImage(benefit.icon);

        previewDocument
          .querySelectorAll(`[data-key-path="${itemPath}.icon"]`)
          .forEach((image) => {
            if (iconUrl) {
              image.src = iconUrl;
            } else {
              image.removeAttribute('src');
            }

            const alt = benefit.iconAlt ?? '';
            image.alt = alt;
            image.setAttribute('aria-hidden', String(alt === ''));
          });
      });
    }

    // How It Works Section
    if (howItWorks) {
      setText('how_it_works.heading', howItWorks.heading);

      // Update card background images
      const backgroundUrl = resolveImage(howItWorks.background_image);

      previewDocument
        .querySelectorAll('[data-key-path="how_it_works.background_image"]')
        .forEach((element) => {
          element.style.backgroundImage = backgroundUrl
            ? `url("${backgroundUrl}")`
            : '';
        });

      // Update each step
      (howItWorks.steps ?? []).forEach((step, index) => {
        const itemPath = `how_it_works.steps.${index}`;

        setText(`${itemPath}.title`, `${index + 1}. ${step.title}`);
        setText(`${itemPath}.description`, step.description);

        const imageUrl = resolveImage(step.image);

        previewDocument
          .querySelectorAll(`[data-key-path="${itemPath}.image"]`)
          .forEach((image) => {
            if (imageUrl) image.src = imageUrl;
            else image.removeAttribute('src');

            image.alt = step.image_alt ?? '';
          });
      });
    }

    // Our Services Section
    if (services) {
      setText('services.heading', services.heading);

      (services.items ?? []).forEach((service, index) => {
        const itemPath = `services.items.${index}`;

        setText(`${itemPath}.title`, service.title);
        setText(`${itemPath}.description`, service.description);

        const iconUrl = resolveImage(service.icon);

        previewDocument
          .querySelectorAll(`[data-key-path="${itemPath}.icon"]`)
          .forEach((image) => {
            if (iconUrl) image.src = iconUrl;
            else image.removeAttribute('src');
          });
      });
    }

    // Drive With Us Section
    if (driveWithUs) {
      setText('drive_with_us.heading', driveWithUs.heading);
      setText('drive_with_us.description', driveWithUs.description);
      setText('drive_with_us.button_text', driveWithUs.button_text);

      // Update application button URL
      previewDocument
        .querySelectorAll('[data-key-path="drive_with_us.button_text"]')
        .forEach((element) => {
          element.href = driveWithUs.button_url ?? '';
        });

      // Update driver benefits
      (driveWithUs.benefits ?? []).forEach((benefit, index) => {
        const itemPath = `drive_with_us.benefits.${index}`;

        setText(`${itemPath}.title`, benefit.title);
        setText(`${itemPath}.description`, benefit.description);

        const iconUrl = resolveImage(benefit.icon);

        previewDocument
          .querySelectorAll(`[data-key-path="${itemPath}.icon"]`)
          .forEach((image) => {
            if (iconUrl) image.src = iconUrl;
            else image.removeAttribute('src');
          });
      });
    }

    // Ride Options Section
    if (rideOptions) {
      setText('ride_options.heading', rideOptions.heading);

      (rideOptions.items ?? []).forEach((option, index) => {
        const itemPath = `ride_options.items.${index}`;

        setText(`${itemPath}.title`, option.title);
        setText(`${itemPath}.description`, option.description);

        const iconUrl = resolveImage(option.icon);

        previewDocument
          .querySelectorAll(`[data-key-path="${itemPath}.icon"]`)
          .forEach((image) => {
            if (iconUrl) image.src = iconUrl;
            else image.removeAttribute('src');
          });
      });
    }

    // Promotional Banners Section
    if (promotionalBanners) {
      (promotionalBanners.items ?? []).forEach((promotion, index) => {
        const itemPath = `promotional_banners.items.${index}`;

        setText(`${itemPath}.heading`, promotion.heading);
        setText(`${itemPath}.button_text`, promotion.button_text);

        previewDocument
          .querySelectorAll(`[data-key-path="${itemPath}.button_text"]`)
          .forEach((element) => {
            element.href = promotion.button_url ?? '';
          });
      });
    }

    // Easy Registration Section
    if (easyRegistration) {
      setText('easy_registration.heading', easyRegistration.heading);
      setText('easy_registration.description', easyRegistration.description);

      (easyRegistration.items ?? []).forEach((item, index) => {
        const itemPath = `easy_registration.items.${index}`;

        setText(`${itemPath}.title`, item.title);

        const imageUrl = resolveImage(item.image);

        previewDocument
          .querySelectorAll(`[data-key-path="${itemPath}.image"]`)
          .forEach((image) => {
            if (imageUrl) image.src = imageUrl;
            else image.removeAttribute('src');

            image.alt = item.image_alt ?? '';
          });

        previewDocument
          .querySelectorAll(`[data-key-path="${itemPath}.url"]`)
          .forEach((element) => {
            element.href = item.url ?? '';
          });
      });
    }

    // What Our Riders Say Section
    if (testimonials) {
      setText('testimonials.heading', testimonials.heading);

      (testimonials.items ?? []).forEach((testimonial, index) => {
        const itemPath = `testimonials.items.${index}`;

        setText(`${itemPath}.quote`, testimonial.quote);
        setText(`${itemPath}.name`, testimonial.name);
        setText(`${itemPath}.location`, testimonial.location);

        const ratingContainer = previewDocument.querySelector(
          `[data-key-path="${itemPath}.rating"]`
        );

        if (ratingContainer) {
          ratingContainer.innerHTML = '';

          ratingContainer.setAttribute(
            'aria-label',
            `${testimonial.rating} out of 5 stars`
          );

          for (let i = 0; i < testimonial.rating; i++) {
            const star = previewDocument.createElement('img');
            star.src = resolveImage('assets/img/icon/shaded-star.svg');
            star.alt = '';
            star.setAttribute('aria-hidden', 'true');
            star.className = 'size-5 shrink-0';

            ratingContainer.appendChild(star);
          }
        }
      });
    }

    // Safety & Support Section
    if (safetySupport) {
      setText('safety_support.heading', safetySupport.heading);

      (safetySupport.items ?? []).forEach((feature, index) => {
        const itemPath = `safety_support.items.${index}`;

        setText(`${itemPath}.title`, feature.title);
        setText(`${itemPath}.description`, feature.description);

        const icon = previewDocument.querySelector(
          `[data-key-path="${itemPath}.icon"]`
        );

        if (icon) {
          icon.src = resolveImage(feature.icon);
        }
      });
    }
  }, [entry, getAsset, isReady, previewDocument]);

  return html`
    <div id="nycuno-hero-preview-root">
      Loading NYCUNO preview...
    </div>
  `;
};

CMS.registerPreviewTemplate('homepage', HomepagePreview);
